+  } catch {
+    return out;
+  }
+  const cutoff = now - olderThanMs;
+  const runFiles = new Map<string, string[]>();
+  const xfers = new Map<string, string[]>();
+  for (const n of names) {
+    let m = n.match(/^run-([A-Za-z0-9_-]{1,64})\.(json|sh|log)$/) ?? n.match(/^done-([A-Za-z0-9_-]{1,64})\.json$/);
